@import "../global/variables.css";

@value header from "../island/island.css";

.container {
  position: fixed;
  z-index: var(--ring-overlay-z-index);
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;

  display: flex;
  overflow: auto;
  align-items: center;
  justify-content: center;

