  box-shadow: var(--ring-dialog-shadow);
}

.clickableOverlay {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;

  cursor: pointer;
}

.clickableOverlay:hover + * .closeIcon {
