    const {show, modal} = this.props;
    if (this.nativeDialog.current != null) {
      if (show) {
        modal ? this.nativeDialog.current.showModal() : this.nativeDialog.current.show();
      } else {
        this.nativeDialog.current.close();
      }
    }
  }

