import {mount} from 'enzyme';

import Dialog, {DialogAttrs} from './dialog';
import styles from './dialog.css';

describe('Dialog', () => {
  const children = <div/>;
  const mountDialog = (props: DialogAttrs) =>
    mount<Dialog>(<Dialog label="Dialog" {...props} trapFocus={false}/>);

  it('should create component', () => {
    mountDialog({show: true, children}).should.have.type(Dialog);
  });

  it('should wrap children with dialog wrapper', () => {
    const {dialog} = mountDialog({show: true, children}).instance();
    should.exist(dialog);
    dialog?.should.match(`.${styles.container}`);
  });

  it('should use passed className', () => {
    const {dialog} = mountDialog({show: true, children, className: 'test-class'}).instance();
    should.exist(dialog);
    dialog?.should.match('.test-class');
  });

  it('should call onOverlayClick and onCloseAttempt callbacks on click by overlay', () => {
    const closeSpy = sandbox.spy();
    const clickSpy = sandbox.spy();
    const instance = mountDialog({
      show: true,
      children,
      onOverlayClick: clickSpy,
      onCloseAttempt: closeSpy
    }).instance();
    should.exist(instance.dialog);
    instance.handleClick({target: instance.dialog} as never);

    closeSpy.should.have.been.called;
    clickSpy.should.have.been.called;
  });

  it('should call onEscPress and onCloseAttempt callbacks on click by overlay', () => {
    const closeSpy = sandbox.spy();
    const escSpy = sandbox.spy();
    const instance = mountDialog({
      show: true,
      children,
      onEscPress: escSpy,
      onCloseAttempt: closeSpy
    }).instance();

    instance.getShortcutsMap().esc({} as KeyboardEvent);

    closeSpy.should.have.been.called;
    escSpy.should.have.been.called;
  });

  it('should not call onEscPress if is hidden', () => {
    const escSpy = sandbox.spy();
    const instance = mountDialog({show: false, children, onEscPress: escSpy}).instance();
    instance.getShortcutsMap().esc({} as KeyboardEvent);

    escSpy.should.not.have.been.called;
  });
});

import scrollbarWidth from 'scrollbar-width';

import styles from './dialog.css';

const isPrevented = new Set();
let previousDocumentWidth: string | null = null;

const prevent = (key: string | number) => {
  if (isPrevented.has(key)) {
    return;
  }

  isPrevented.add(key);

  if (isPrevented.size > 1) {
    return;
  }

  const documentHasScroll = document.documentElement.scrollHeight > window.innerHeight ||
    getComputedStyle(document.documentElement).overflowY === 'scroll';
  document.documentElement.classList.add(styles.documentWithoutScroll);

  const scrollWidth = scrollbarWidth();

  if (documentHasScroll && scrollWidth != null && scrollWidth > 0) {
    previousDocumentWidth = document.documentElement.style.width;
    document.documentElement.style.width = `calc(100% - ${scrollWidth}px)`;
  }
};

const reset = (key: string | number) => {
  if (isPrevented.size === 0) {
    return;
  }

  isPrevented.delete(key);

  if (isPrevented.size > 0) {
    return;
  }

  document.documentElement.classList.remove(styles.documentWithoutScroll);

  if (previousDocumentWidth !== null) {
    document.documentElement.style.width = previousDocumentWidth;
    previousDocumentWidth = null;
  }
};

export const preventerFactory = (key: string | number) => {
  const preventerKey = key || Math.random();

  return {
    prevent: () => prevent(preventerKey),
    reset: () => reset(preventerKey)
  };
};

export default preventerFactory('default-preventer');

import {Component, ComponentType, createContext} from 'react';

import {interpolateLinear} from '../global/linear-function';

const TITLE_RESIZE_END = 20;
const TITLE_RESIZE_THRESHOLD = 36;

export const PhaseContext = createContext<number | null>(null);

type ScrollHandler = (element: Element) => void
export const ScrollHandlerContext = createContext<ScrollHandler | null>(null);

export default function adaptiveIslandHOC<P>(ComposedComponent: ComponentType<P>) {

  return class AdaptiveIsland extends Component<P> {
    static propTypes = ComposedComponent.propTypes;

    state = {
      phase: null
    };

    onContentScroll = ({scrollTop, scrollHeight, clientHeight}: Element) => {
      if (scrollHeight - clientHeight >=
        interpolateLinear(TITLE_RESIZE_THRESHOLD, TITLE_RESIZE_END, this.state.phase ?? 0)) {
        const phase = Math.min(1, scrollTop / TITLE_RESIZE_END);
        this.setState({phase});
      }
    };

    render() {
      return (
        <PhaseContext.Provider value={this.state.phase}>
          <ScrollHandlerContext.Provider value={this.onContentScroll}>
            <ComposedComponent {...this.props}/>
          </ScrollHandlerContext.Provider>
        </PhaseContext.Provider>
      );
    }
  };
}

import {Component, HTMLAttributes} from 'react';
import PropTypes from 'prop-types';
import classNames from 'classnames';

import {interpolateLinear} from '../global/linear-function';

import styles from './island.css';
import {PhaseContext} from './adaptive-island-hoc';

const Start = {
  FONT_SIZE: 24,
  LINE_HEIGHT: 28,
  PADDING_TOP: 24,
  PADDING_BOTTOM: 0,
  X: 0,
  Y: 0,
  SPACING: 0
};

const End = {
  FONT_SIZE: 13,
  LINE_HEIGHT: 20,
  PADDING_TOP: 16,
  PADDING_BOTTOM: 8,

  // Compensation
  X: 0.4,
  Y: 0.1,
  SPACING: 1.09
};

const BORDER_APPEAR_PHASE = 0.5;

export interface IslandHeaderProps extends HTMLAttributes<HTMLElement> {
  wrapWithTitle?: boolean | undefined
  border?: boolean | null | undefined
  phase?: number | undefined
}

class Header extends Component<IslandHeaderProps> {
  static propTypes = {
    children: PropTypes.node,
    className: PropTypes.string,
    border: PropTypes.bool,
    wrapWithTitle: PropTypes.bool,
    phase: PropTypes.number
  };

  static defaultProps = {
    wrapWithTitle: true
  };

  style(name: keyof typeof Start) {
    return interpolateLinear(Start[name], End[name], this.props.phase ?? 0);
  }

  render() {
    const {children, className, wrapWithTitle, border, phase, ...restProps} = this.props;
    const classes = classNames(styles.header, className, {
      [styles.withBottomBorder]: border || phase != null && phase >= BORDER_APPEAR_PHASE
    });


    const headerStyle = phase != null
      ? {
        lineHeight: `${this.style('LINE_HEIGHT')}px`, // need to append px because number is a valid line-height value
        paddingTop: this.style('PADDING_TOP'),
        paddingBottom: this.style('PADDING_BOTTOM')
      }
      : undefined;

    const scaleFont = phase != null && this.style('FONT_SIZE') / Start.FONT_SIZE;

    const titleStyle = (phase != null && phase < 1)
      ? {
        fontSize: Start.FONT_SIZE,
        transform: `translate(${this.style('X')}px, ${this.style('Y')}px) scale(${scaleFont})`,
        letterSpacing: this.style('SPACING')
      }
      : undefined;

    return (
      <div
        {...restProps}
        data-test="ring-island-header"
        className={classes}
        style={headerStyle}
      >
        {wrapWithTitle &&
        (
          <h2
            className={styles.title}
            style={titleStyle}
          >
            {children}
          </h2>
        )}

        {!wrapWithTitle && children}

      </div>
    );
  }
}

const HeaderWrapper = (props: IslandHeaderProps) => (
  <PhaseContext.Consumer>
    {phase => {
      const addProps = phase != null ? {phase} : {};
      return <Header {...props} {...addProps}/>;
    }}
  </PhaseContext.Consumer>
);

export default HeaderWrapper;

@import "../global/variables.css";

@value gradientStart: rgba(255, 255, 255, 0);
@value gradientStop: var(--ring-content-background-color);

.island {
  display: flex;
  flex-direction: column;

  border: 1px solid var(--ring-line-color);
  border-radius: var(--ring-border-radius);

  background-color: var(--ring-content-background-color);
  box-shadow: 0 1px 4px var(--ring-popup-shadow-color);
}

.withTransparentBottomBorder {
  transition: border-bottom-color 0.1s;

  border-bottom: 1px solid transparent;
}

.header {
  box-sizing: border-box;
  width: 100%;
  padding: calc(var(--ring-unit) * 2) calc(var(--ring-unit) * 4) var(--ring-unit);

  transition: border-bottom-color 0.1s;

  border-bottom: 1px solid transparent;

  line-height: 24px;
}

.withBottomBorder.withBottomBorder {
  border-bottom-color: var(--ring-popup-border-color);
  border-top-left-radius: var(--ring-border-radius);
  border-top-right-radius: var(--ring-border-radius);
}

.title {
  display: block;
  float: left;

  margin: 0;

  transform-origin: 0 50%;
  word-break: break-word;

  color: var(--ring-heading-color);

  font-size: inherit;

  font-weight: bold;
}

.narrowIsland .header {
  padding: 0 calc(var(--ring-unit) * 2);
}

.content {
  position: relative;

  display: flex;
  overflow: auto;

  width: 100%;
  -webkit-overflow-scrolling: touch;
}

.scrollableWrapper {
  overflow: auto;

  width: 100%;
  padding: calc(var(--ring-unit) * 2) calc(var(--ring-unit) * 4);

  &:focus:not(:focus-visible) {
    outline: none;
  }
}

.narrowIsland .scrollableWrapper {
  padding: calc(var(--ring-unit) * 2);
}

.withoutPaddings .scrollableWrapper {
  padding: 0;
}

.contentWithTopFade::before {
  position: absolute;
  z-index: var(--ring-fixed-z-index);
  left: 0;

  display: block;

  width: 100%;
  height: calc(var(--ring-unit) * 3);

  content: "";

  pointer-events: none;

  opacity: 0.8;

  background: linear-gradient(to top, gradientStart, gradientStop);
}

.contentWithTopFade:first-child::before {
  border-top-left-radius: var(--ring-border-radius);
  border-top-right-radius: var(--ring-border-radius);
}

.contentWithBottomFade::after {
  position: absolute;
  bottom: 0;
  left: 0;

  display: block;

  width: 100%;
  height: calc(var(--ring-unit) * 3);

  content: "";
  pointer-events: none;

  opacity: 0.8;
  border-bottom-right-radius: var(--ring-border-radius);
  border-bottom-left-radius: var(--ring-border-radius);
  background: linear-gradient(to bottom, gradientStart, gradientStop);
}

import {shallow, mount} from 'enzyme';

import Island, {AdaptiveIsland, Content, Header, IslandProps} from './island';

describe('Island', () => {
  const shallowIsland = (params?: IslandProps) => shallow(<Island {...params}/>);
  const mountIsland = (params?: IslandProps) => mount(<Island {...params}/>);

  it('should create Island component', () => {
    mountIsland().should.have.type(Island);
  });

  it('should wrap children with div', () => {
    shallowIsland().should.have.tagName('div');
  });

  it('should use passed className', () => {
    shallowIsland({className: 'test-class'}).should.have.className('test-class');
  });

  it('should join with passed data-test', () => {
    shallowIsland({['data-test']: 'foobar'}).should.have.attr('data-test', 'ring-island foobar');
  });

  describe('AdaptiveIsland', () => {
    it('should render AdaptiveIsland', () => {
      mount(<AdaptiveIsland/>).should.have.type(AdaptiveIsland);
    });

    it('should change header size if content is scrolled', () => {
      const wrapper = mount<InstanceType<typeof AdaptiveIsland>>(
        <AdaptiveIsland>
          <Header/>
          <Content/>
        </AdaptiveIsland>
      );

      const headerNode = wrapper.find('[data-test="ring-island-header"]');

      wrapper.instance().onContentScroll({
        scrollTop: 10,
        scrollHeight: 100,
        clientHeight: 50
      } as Element);
      headerNode.should.have.style('line-height', '24px');
    });
  });

  describe('Header', () => {
    it('should render header', () => {
      mount(<Header/>).should.have.type(Header);
    });

    it('should change header size', () => {
      const phase = 0.75;
      const wrapper = shallow(<Header phase={phase}/>);
      wrapper.should.have.style('line-height', '22px');
    });
  });
});

import {Component, HTMLAttributes} from 'react';
import PropTypes from 'prop-types';
import classNames from 'classnames';

import dataTests from '../global/data-tests';

import adaptiveIslandHOC from './adaptive-island-hoc';

import styles from './island.css';

export interface IslandProps extends HTMLAttributes<HTMLElement> {
  narrow?: boolean | null | undefined
  withoutPaddings?: boolean | null | undefined
  'data-test'?: string | null | undefined
}

/**
 * @name Island
 */

export default class Island extends Component<IslandProps> {
  static propTypes = {
    children: PropTypes.node,
    className: PropTypes.string,
    narrow: PropTypes.bool,
    withoutPaddings: PropTypes.bool,
    'data-test': PropTypes.string
  };

  render() {
    const {
      children,
      className,
      narrow,
      withoutPaddings,
      'data-test': dataTest,
      ...restProps
    } = this.props;
    const classes = classNames(styles.island, className, {
      [styles.narrowIsland]: narrow,
      [styles.withoutPaddings]: withoutPaddings
    });

    return (
      <div
        {...restProps}
        className={classes}
        data-test={dataTests('ring-island', dataTest)}
      >
        {children}
      </div>
    );
  }
}

export const AdaptiveIsland = adaptiveIslandHOC(Island);

export {default as Header} from './header';
export {default as Content} from './content';

